From a97f74302cf6d4300f457554123e245dd9b9f248 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 00:13:57 +0100
Subject: [PATCH] containments/desktop: Add "Create New" to the folder icons
 context menu

Right-clicking a desktop folder gave no way to create items inside it,
unlike Dolphin. Show the Create New submenu aimed at that folder, and
only give new items a desktop position if they land on the desktop.

BUG: 451215
---
 .../desktop/plugins/folder/foldermodel.cpp    | 34 +++++++++++++++----
 1 file changed, 27 insertions(+), 7 deletions(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..3cad6e297a 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -393,7 +393,11 @@ void FolderModel::newFileMenuItemCreationStarted(const QUrl &url)

 void FolderModel::newFileMenuItemCreated(const QUrl &url)
 {
-    if (m_usedByContainment && !m_screenMapper->sharedDesktops()) {
+    const QUrl parentUrl = url.adjusted(QUrl::RemoveFilename | QUrl::StripTrailingSlash);
+    const bool isInThisFolder =
+        parentUrl == resolvedUrl().adjusted(QUrl::StripTrailingSlash) || parentUrl == rootItem().mostLocalUrl().adjusted(QUrl::StripTrailingSlash);
+
+    if (m_usedByContainment && !m_screenMapper->sharedDesktops() && isInThisFolder) {
         m_screenMapper->addMapping(url, m_screen, m_currentActivity, ScreenMapper::DelayedSignal);
         m_dropTargetPositions.insert(url.fileName(), localMenuPosition());
         m_menuPosition = {};
@@ -1949,16 +1953,26 @@ void FolderModel::updateActions()
         showTarget->setEnabled(items.count() == 1 && items.at(0).isLink());
     }

-    if (m_newMenu) {
+    // target directory associated with the current context menu actions
+    const auto contextWorkDir = [&]() -> std::optional<QUrl> {
+        if (indexes.count() == 1 && items.first().isDir()) {
+            return items.first().targetUrl();
+        }
+        if (indexes.isEmpty() && !isTrash) {
+            return m_dirModel->dirLister()->url();
+        }
+        return std::nullopt;
+    }();
+    if (contextWorkDir) {
         m_newMenu->checkUpToDate();
-        m_newMenu->setWorkingDirectory(m_dirModel->dirLister()->url());
+        m_newMenu->setWorkingDirectory(*contextWorkDir);
         // we need to set here as well, when the menu is shown via AppletInterface::eventFilter
         m_menuPosition = QCursor::pos();

-        if (QAction *newMenuAction = m_actionCollection.action(QStringLiteral("newMenu"))) {
-            newMenuAction->setEnabled(itemProperties.supportsWriting());
-            newMenuAction->setVisible(!isTrash);
-        }
+        m_newMenu->setEnabled(itemProperties.supportsWriting());
+        m_newMenu->setVisible(true);
+    } else {
+        m_newMenu->setVisible(false);
     }

     if (QAction *moveToTrash = m_actionCollection.action(QStringLiteral("trash"))) {
@@ -2080,6 +2094,12 @@ void FolderModel::openContextMenu(QQuickItem *visualParent, Qt::KeyboardModifier
             m_fileItemActions->insertOpenWithActionsTo(nullptr, menu, QStringList());
         }

+        // isVisible is kept up to date inside ::updateActions()
+        if (m_newMenu->isVisible()) {
+            menu->addAction(m_newMenu);
+            menu->addSeparator();
+        }
+
         if (!isTrash) {
             menu->addAction(m_actionCollection.action(QStringLiteral("emptyTrash")));
         } else {
-- 
